functions.og_redeem_voucher:
CREATE OR REPLACE FUNCTION public.og_redeem_voucher()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
DECLARE v voucher_grants; r voucher_revisions; base NUMERIC; benefit NUMERIC;
BEGIN
    SELECT * INTO STRICT v FROM voucher_grants WHERE grant_id=NEW.grant_id FOR UPDATE;
    SELECT * INTO STRICT r FROM voucher_revisions WHERE revision_id=v.revision_id FOR UPDATE;
    IF v.state<>'AVAILABLE' OR v.expires_at<=NEW.redeemed_at THEN
        RAISE EXCEPTION 'Voucher already used/revoked/expired' USING ERRCODE='23514';
    END IF;
    IF r.benefit_component='GOODS' THEN
        SELECT COALESCE(sum(i.agreed_price*i.quantity),0) INTO base FROM order_items i JOIN orders o USING(order_id)
            WHERE o.group_id=NEW.group_id AND (r.scope='CHECKOUT' OR EXISTS(SELECT 1 FROM voucher_revision_products
                WHERE revision_id=r.revision_id AND product_id=i.product_id));
    ELSE SELECT COALESCE(sum(shipping_fee),0) INTO base FROM orders WHERE group_id=NEW.group_id; END IF;
    benefit:=LEAST(base,CASE WHEN r.discount_type='FIXED_AMOUNT' THEN r.discount_value
        ELSE round(base*r.discount_value/100,0) END,COALESCE(r.max_discount_amount,base));
    IF base<r.min_eligible_amount OR NEW.discount_amount<>benefit OR EXISTS(
        SELECT 1 FROM voucher_revision_revocations WHERE revision_id=r.revision_id) THEN
        RAISE EXCEPTION 'Voucher amount/minimum/revocation differs from immutable policy' USING ERRCODE='23514'; END IF;
    NEW.policy_snapshot:=r.policy_snapshot||jsonb_build_object('benefit_component',r.benefit_component,
        'discount_type',r.discount_type,'discount_value',r.discount_value,'max_discount_amount',r.max_discount_amount,
        'min_eligible_amount',r.min_eligible_amount,'scope',r.scope);
    UPDATE voucher_grants SET state='REDEEMED' WHERE grant_id=v.grant_id;
    RETURN NEW;
END;
$function$

functions.og_lock_money_hold:
CREATE OR REPLACE FUNCTION public.og_lock_money_hold()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
BEGIN
    PERFORM 1 FROM orders WHERE order_id=(SELECT order_id FROM order_fund_components WHERE component_id=NEW.component_id) FOR UPDATE;
    PERFORM 1 FROM order_fund_components WHERE component_id=NEW.component_id FOR UPDATE;
    IF TG_OP='UPDATE' AND (NEW.component_id<>OLD.component_id OR NEW.source_key<>OLD.source_key
       OR OLD.closed_at IS NOT NULL) THEN RAISE EXCEPTION 'Hold history is immutable' USING ERRCODE='23514'; END IF;
    RETURN NEW;
END;
$function$

functions.og_guard_case_event:
CREATE OR REPLACE FUNCTION public.og_guard_case_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
DECLARE c cases; o orders;
BEGIN
    SELECT * INTO STRICT c FROM cases WHERE case_id=NEW.case_id FOR UPDATE;
    NEW.occurred_at:=clock_timestamp();
    IF NEW.event_type='ESCALATED' AND (NOT og_has_role(NEW.actor_id,'KTV') OR
        NOT og_has_role(NEW.recipient_id,'ADMIN')) THEN
        RAISE EXCEPTION 'Escalation needs KTV to Admin' USING ERRCODE='23514';
    END IF;
    IF NEW.event_type='VALID_DAMAGE_REQUEST' THEN
        SELECT * INTO STRICT o FROM orders WHERE order_id=c.order_id;
        IF NEW.actor_id<>o.seller_id OR c.valid_returned_at IS NULL OR NEW.occurred_at>c.seller_response_due_at
            OR NOT EXISTS(SELECT 1 FROM case_rounds WHERE round_id=NEW.round_id
                AND stage='POST_RETURN_RESOLUTION' AND state='OPEN')
            OR NOT EXISTS(SELECT 1 FROM case_evidence WHERE round_id=NEW.round_id AND submitted_by=NEW.actor_id) THEN
            RAISE EXCEPTION 'Only complete in-time Seller request blocks auto refund' USING ERRCODE='23514';
        END IF;
        UPDATE case_rounds SET valid_damage_request_at=NEW.occurred_at WHERE round_id=NEW.round_id;
    END IF;
    RETURN NEW;
END;
$function$

functions.og_guard_case_round:
CREATE OR REPLACE FUNCTION public.og_guard_case_round()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
DECLARE c cases;
BEGIN
    SELECT * INTO STRICT c FROM cases WHERE case_id=NEW.case_id FOR UPDATE;
    IF (c.case_type='SYSTEM_ISSUE')<>(NEW.stage='SYSTEM_REVIEW') OR
        (NEW.stage='POST_RETURN_RESOLUTION' AND c.valid_returned_at IS NULL) THEN
        RAISE EXCEPTION 'Case round stage incompatible with case/delivery' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$function$

functions.og_guard_return_case:
CREATE OR REPLACE FUNCTION public.og_guard_return_case()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
DECLARE o orders;
BEGIN
    IF NEW.state<>'OPEN' THEN RAISE EXCEPTION 'New case starts open' USING ERRCODE='23514'; END IF;
    IF NEW.case_type='RETURN' AND TG_OP='INSERT' THEN
        SELECT * INTO STRICT o FROM orders WHERE order_id=NEW.order_id FOR UPDATE;
        NEW.created_at:=clock_timestamp();
        IF o.workflow_model<>'UC83' OR NEW.created_by<>o.buyer_id OR NOT o.return_allowed
            OR o.valid_delivered_at IS NULL OR o.early_completed_at IS NOT NULL
            OR NEW.created_at>o.valid_delivered_at+INTERVAL '3 days' THEN
            RAISE EXCEPTION 'Order has no current right to request return' USING ERRCODE='23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

functions.og_apply_reward_entry:
CREATE OR REPLACE FUNCTION public.og_apply_reward_entry()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
DECLARE b BIGINT;
BEGIN
    SELECT balance INTO STRICT b FROM reward_accounts WHERE user_id=NEW.user_id FOR UPDATE;
    IF b+NEW.points_delta<0 OR (NEW.entry_type='CREDIT_COMPLETION' AND NOT EXISTS(
        SELECT 1 FROM orders WHERE order_id=NEW.order_id AND status='COMPLETED'
            AND NEW.user_id IN (buyer_id,seller_id)))
        OR (NEW.entry_type='CORRECTION' AND NOT og_has_role(NEW.actor_id,'ADMIN')) THEN
        RAISE EXCEPTION 'Reward source/balance not eligible' USING ERRCODE='23514';
    END IF;
    UPDATE reward_accounts SET balance=balance+NEW.points_delta,version=version+1 WHERE user_id=NEW.user_id;
    RETURN NEW;
END;
$function$

functions.og_guard_ekyc_attempt:
CREATE OR REPLACE FUNCTION public.og_guard_ekyc_attempt()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
DECLARE p ekyc_profiles;
BEGIN
    SELECT * INTO STRICT p FROM ekyc_profiles WHERE profile_id=NEW.profile_id FOR UPDATE;
    IF p.state NOT IN ('DRAFT','IN_PROGRESS') THEN
        RAISE EXCEPTION 'eKYC input is closed' USING ERRCODE='23514';
    END IF;
    NEW.attempted_at := clock_timestamp();
    IF NEW.result='MANUAL_REVIEW' AND NOT og_has_role(NEW.fallback_authorized_by,'ADMIN') THEN
        RAISE EXCEPTION 'Manual fallback requires Admin' USING ERRCODE='23514';
    END IF;
    IF NEW.result='NON_MATCH' THEN
        IF p.nonmatch_count >= 15 OR
           (p.last_nonmatch_at IS NOT NULL AND NEW.attempted_at < p.last_nonmatch_at + INTERVAL '3 seconds') THEN
            RAISE EXCEPTION 'eKYC attempt limit/cooldown' USING ERRCODE='23514';
        END IF;
        UPDATE ekyc_profiles SET nonmatch_count=nonmatch_count+1,last_nonmatch_at=NEW.attempted_at
            WHERE profile_id=p.profile_id;
    END IF;
    RETURN NEW;
END;
$function$

functions.og_apply_case_decision:
CREATE OR REPLACE FUNCTION public.og_apply_case_decision()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
DECLARE r case_rounds; c cases; o orders;
BEGIN
    NEW.decided_at:=clock_timestamp();
    IF NEW.supersedes_decision_id IS NOT NULL OR (NEW.outcome<>'SELLER_DECLINED' AND NOT NEW.is_final) THEN
        RAISE EXCEPTION 'Final decisions retained; reopening needs a separate authorized round' USING ERRCODE='23514';
    END IF;
    SELECT * INTO STRICT r FROM case_rounds WHERE round_id=NEW.round_id FOR UPDATE;
    SELECT * INTO STRICT c FROM cases WHERE case_id=r.case_id FOR UPDATE;
    IF r.state<>'OPEN' AND NEW.supersedes_decision_id IS NULL THEN
        RAISE EXCEPTION 'Case round already decided' USING ERRCODE='23514';
    END IF;
    IF c.order_id IS NOT NULL THEN SELECT * INTO STRICT o FROM orders WHERE order_id=c.order_id FOR UPDATE; END IF;
    IF r.stage='RETURN_APPROVAL' THEN
        IF NEW.actor_type<>'USER' OR NEW.outcome NOT IN ('APPROVE_RETURN','REJECT_RETURN','SELLER_DECLINED')
            OR NOT (og_has_role(NEW.reviewed_by,'KTV') OR
                (NEW.reviewed_by=o.seller_id AND NEW.outcome IN ('APPROVE_RETURN','SELLER_DECLINED'))) THEN
            RAISE EXCEPTION 'Return approval authority/outcome mismatch' USING ERRCODE='23514';
        END IF;
        IF NEW.outcome='APPROVE_RETURN' THEN
            UPDATE cases SET state='RETURN_APPROVED',approved_at=NEW.decided_at WHERE case_id=c.case_id;
        ELSIF NEW.outcome='REJECT_RETURN' THEN
            UPDATE cases SET state='REJECTED',closed_at=NEW.decided_at WHERE case_id=c.case_id;
        END IF;
    ELSIF r.stage='POST_RETURN_RESOLUTION' THEN
        IF c.valid_returned_at IS NULL OR NEW.outcome NOT IN ('FULL_GOODS_REFUND','EXEMPT_GOODS_REFUND') THEN
            RAISE EXCEPTION 'Post-return decision needs valid returned delivery' USING ERRCODE='23514';
        END IF;
        IF NEW.outcome='EXEMPT_GOODS_REFUND' AND (NEW.actor_type<>'USER' OR NOT og_has_role(NEW.reviewed_by,'KTV')
            OR r.valid_damage_request_at IS NULL) THEN
            RAISE EXCEPTION 'Only KTV may grant exemption after valid request' USING ERRCODE='23514';
        END IF;
        IF NEW.actor_type='SYSTEM_TIMEOUT' AND (NEW.outcome<>'FULL_GOODS_REFUND'
            OR NEW.decided_at<c.seller_response_due_at OR r.valid_damage_request_at IS NOT NULL) THEN
            RAISE EXCEPTION 'Auto refund blocked by deadline/request' USING ERRCODE='23514';
        END IF;
        IF NEW.actor_type='USER' AND NOT (og_has_role(NEW.reviewed_by,'KTV')
            OR (NEW.reviewed_by=o.seller_id AND NEW.outcome='FULL_GOODS_REFUND')) THEN
            RAISE EXCEPTION 'Post-return decision authority mismatch' USING ERRCODE='23514';
        END IF;
        NEW.goods_refund_amount:=CASE WHEN NEW.outcome='FULL_GOODS_REFUND'
            THEN o.subtotal-o.voucher_discount_amount-o.points_discount_amount ELSE 0 END;
        UPDATE cases SET state='CLOSED',closed_at=NEW.decided_at WHERE case_id=c.case_id;
    ELSE
        IF NEW.outcome<>'SYSTEM_RESOLVED' OR NEW.actor_type<>'USER' OR
            NOT (og_has_role(NEW.reviewed_by,'KTV') OR og_has_role(NEW.reviewed_by,'ADMIN')) THEN
            RAISE EXCEPTION 'System issue authority mismatch' USING ERRCODE='23514';
        END IF;
        UPDATE cases SET state='CLOSED',closed_at=NEW.decided_at WHERE case_id=c.case_id;
    END IF;
    IF NEW.is_final THEN UPDATE case_rounds SET state='DECIDED' WHERE round_id=r.round_id; END IF;
    RETURN NEW;
END;
$function$

functions.og_apply_ekyc_decision:
CREATE OR REPLACE FUNCTION public.og_apply_ekyc_decision()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
DECLARE p ekyc_profiles;
BEGIN
    NEW.decided_at:=clock_timestamp();
    SELECT * INTO STRICT p FROM ekyc_profiles WHERE profile_id=NEW.profile_id FOR UPDATE;
    IF p.state<>'PENDING' OR NOT og_has_role(NEW.reviewed_by,'KTV') THEN
        RAISE EXCEPTION 'Only KTV can decide a pending eKYC revision' USING ERRCODE='23514';
    END IF;
    IF NEW.outcome='VERIFIED' AND (
        p.document_digest IS NULL
        OR (SELECT count(DISTINCT asset_type) FROM ekyc_private_assets
            WHERE profile_id=p.profile_id AND deleted_at IS NULL AND expires_at>NEW.decided_at
              AND asset_type IN ('CARD_FRONT','CARD_BACK','LIVE_FRAME','REFERENCE')) <> 4) THEN
        RAISE EXCEPTION 'eKYC identity/private evidence incomplete' USING ERRCODE='23514';
    END IF;
    UPDATE ekyc_profiles SET state=NEW.outcome,
        verified_at=CASE WHEN NEW.outcome='VERIFIED' THEN NEW.decided_at END,
        reference_expires_at=CASE WHEN NEW.outcome='VERIFIED' THEN
            LEAST(NEW.decided_at+INTERVAL '3 months',
                (SELECT min(expires_at) FROM ekyc_private_assets WHERE profile_id=p.profile_id AND deleted_at IS NULL)) END,
        version=version+1 WHERE profile_id=p.profile_id;
    RETURN NEW;
END;
$function$

functions.og_guard_case_evidence:
CREATE OR REPLACE FUNCTION public.og_guard_case_evidence()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
DECLARE r case_rounds; c cases; o orders; n INTEGER;
BEGIN
    SELECT * INTO STRICT r FROM case_rounds WHERE round_id=NEW.round_id FOR UPDATE;
    SELECT * INTO STRICT c FROM cases WHERE case_id=r.case_id;
    IF r.state<>'OPEN' THEN RAISE EXCEPTION 'Evidence round closed' USING ERRCODE='23514'; END IF;
    NEW.submitted_at:=clock_timestamp();
    IF c.order_id IS NOT NULL THEN
        SELECT * INTO STRICT o FROM orders WHERE order_id=c.order_id;
        IF NEW.submitted_by NOT IN (o.buyer_id,o.seller_id) AND NOT og_has_role(NEW.submitted_by,'KTV') THEN
            RAISE EXCEPTION 'Evidence author not a party/KTV' USING ERRCODE='23514';
        END IF;
        IF NEW.submitted_by=o.buyer_id AND c.case_type='RETURN'
            AND NEW.submitted_at>o.valid_delivered_at+INTERVAL '3 days' THEN
            RAISE EXCEPTION 'Buyer evidence submission deadline passed' USING ERRCODE='23514';
        END IF;
    ELSIF NEW.submitted_by<>c.created_by AND NOT og_has_role(NEW.submitted_by,'KTV') THEN
        RAISE EXCEPTION 'Private system issue evidence author invalid' USING ERRCODE='23514';
    END IF;
    SELECT count(*) INTO n FROM case_evidence WHERE round_id=NEW.round_id
        AND submitted_by=NEW.submitted_by AND submission_no=NEW.submission_no AND media_type=NEW.media_type;
    IF (NEW.media_type='IMAGE' AND n>=5) OR (NEW.media_type='VIDEO' AND n>=2) THEN
        RAISE EXCEPTION 'Evidence submission media limit exceeded' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$function$

functions.og_guard_checkout_item:
CREATE OR REPLACE FUNCTION public.og_guard_checkout_item()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
DECLARE o orders; p products; r product_revisions;
BEGIN
    IF TG_OP='DELETE' THEN
        IF OLD.workflow_model='UC83' THEN RAISE EXCEPTION 'Order item history retained' USING ERRCODE='23514'; END IF;
        RETURN OLD;
    END IF;
    SELECT * INTO STRICT o FROM orders WHERE order_id=NEW.order_id;
    IF NEW.workflow_model<>o.workflow_model THEN RAISE EXCEPTION 'Item workflow mismatch' USING ERRCODE='23514'; END IF;
    IF NEW.workflow_model='UC83' THEN
        SELECT * INTO STRICT p FROM products WHERE product_id=NEW.product_id;
        SELECT * INTO STRICT r FROM product_revisions WHERE revision_id=NEW.product_revision_id;
        IF p.seller_id<>o.seller_id OR NEW.return_allowed IS DISTINCT FROM o.return_allowed
           OR NEW.return_allowed IS DISTINCT FROM r.return_allowed OR NEW.listed_price<>r.listed_unit_price
           OR NOT (r.delivery_options ? o.delivery_method) THEN
            RAISE EXCEPTION 'Seller/return/delivery/price snapshot mismatch' USING ERRCODE='23514';
        END IF;
        IF NEW.accepted_offer_id IS NOT NULL AND NOT EXISTS(
            SELECT 1 FROM offers offer JOIN conversations c USING(conversation_id)
            WHERE offer.offer_id=NEW.accepted_offer_id AND offer.status='ACCEPTED'
              AND c.buyer_id=o.buyer_id AND c.seller_id=o.seller_id AND c.product_id=NEW.product_id
              AND offer.offered_item_price=NEW.agreed_price) THEN
            RAISE EXCEPTION 'Accepted offer belongs to another transaction' USING ERRCODE='23514';
        END IF;
        IF TG_OP='UPDATE' AND NEW IS DISTINCT FROM OLD THEN
            RAISE EXCEPTION 'UC83 order item snapshot is immutable' USING ERRCODE='23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

functions.og_guard_penalty_entry:
CREATE OR REPLACE FUNCTION public.og_guard_penalty_entry()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
DECLARE points BIGINT;
BEGIN
    PERFORM 1 FROM users WHERE user_id=NEW.user_id FOR UPDATE;
    SELECT COALESCE(sum(points_delta),0) INTO points FROM penalty_ledger WHERE user_id=NEW.user_id;
    IF NOT og_has_role(NEW.decided_by,'KTV') OR points+NEW.points_delta<0
        OR (NEW.points_delta>0 AND NOT EXISTS(SELECT 1 FROM reports
            WHERE report_id=NEW.report_id AND status='RESOLVED'))
        OR (NEW.adjustment_of IS NOT NULL AND NOT EXISTS(SELECT 1 FROM penalty_ledger
            WHERE entry_id=NEW.adjustment_of AND user_id=NEW.user_id)) THEN
        RAISE EXCEPTION 'Penalty requires confirmed KTV violation/correction' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$function$

functions.og_guard_private_asset:
CREATE OR REPLACE FUNCTION public.og_guard_private_asset()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
BEGIN
    IF TG_OP='DELETE' OR (TG_OP='UPDATE' AND ROW(NEW.profile_id,NEW.asset_type,NEW.object_key,
        NEW.content_digest,NEW.captured_at,NEW.expires_at) IS DISTINCT FROM
        ROW(OLD.profile_id,OLD.asset_type,OLD.object_key,OLD.content_digest,OLD.captured_at,OLD.expires_at)) THEN
        RAISE EXCEPTION 'Private evidence identity retained; mark deletion only' USING ERRCODE='23514';
    END IF;
    IF TG_OP='INSERT' AND NOT EXISTS(SELECT 1 FROM ekyc_profiles WHERE profile_id=NEW.profile_id
        AND state IN ('DRAFT','IN_PROGRESS')) THEN
        RAISE EXCEPTION 'Only open eKYC accepts new evidence' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$function$

functions.og_guard_voucher_grant:
CREATE OR REPLACE FUNCTION public.og_guard_voucher_grant()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
DECLARE r voucher_revisions;
BEGIN
    SELECT * INTO STRICT r FROM voucher_revisions WHERE revision_id=NEW.revision_id FOR UPDATE;
    IF NEW.state<>'AVAILABLE' OR NEW.expires_at>r.valid_until OR NEW.expires_at<=NEW.granted_at
        OR EXISTS(SELECT 1 FROM voucher_revision_revocations WHERE revision_id=r.revision_id)
        OR NEW.granted_at<r.valid_from OR NEW.granted_at>=r.valid_until
        OR (NEW.source='SELF_CLAIM' AND NEW.issued_by<>NEW.user_id)
        OR (NEW.source<>'SELF_CLAIM' AND (NOT og_has_role(NEW.issued_by,'KTV') OR NULLIF(btrim(NEW.reason),'') IS NULL))
        OR (SELECT count(*) FROM voucher_grants WHERE revision_id=r.revision_id AND user_id=NEW.user_id)>=r.per_user_claim_limit
        OR (r.claim_limit IS NOT NULL AND (SELECT count(*) FROM voucher_grants WHERE revision_id=r.revision_id)>=r.claim_limit) THEN
        RAISE EXCEPTION 'Voucher grant not eligible or claim limit exceeded' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$function$

functions.og_validate_case_state:
CREATE OR REPLACE FUNCTION public.og_validate_case_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
DECLARE c cases;
BEGIN
    SELECT * INTO STRICT c FROM cases WHERE case_id=NEW.case_id;
    IF (c.approved_at IS NOT NULL AND NOT EXISTS(SELECT 1 FROM case_decisions d JOIN case_rounds r USING(round_id)
        WHERE r.case_id=c.case_id AND d.outcome='APPROVE_RETURN' AND d.is_final))
        OR (c.state IN ('CLOSED','REJECTED') AND NOT EXISTS(SELECT 1 FROM case_decisions d JOIN case_rounds r USING(round_id)
            WHERE r.case_id=c.case_id AND d.is_final AND d.outcome IN
                ('REJECT_RETURN','FULL_GOODS_REFUND','EXEMPT_GOODS_REFUND','SYSTEM_RESOLVED')))
        OR (c.valid_returned_at IS NOT NULL AND NOT EXISTS(SELECT 1 FROM shipments s
            WHERE s.return_case_id=c.case_id AND s.leg='RETURN' AND s.valid_delivery_at=c.valid_returned_at)) THEN
        RAISE EXCEPTION 'Case state requires corresponding decision/delivery proof' USING ERRCODE='23514';
    END IF;
    RETURN NULL;
END;
$function$

functions.og_consume_handover_otp:
CREATE OR REPLACE FUNCTION public.og_consume_handover_otp(p_shipment bigint, p_buyer bigint, p_digest text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
DECLARE s shipments;
BEGIN
    PERFORM 1 FROM orders WHERE order_id=(SELECT order_id FROM shipments WHERE shipment_id=p_shipment) FOR UPDATE;
    SELECT * INTO STRICT s FROM shipments WHERE shipment_id=p_shipment FOR UPDATE;
    IF s.workflow_model<>'UC83' OR s.delivery_method='CARRIER' OR NOT EXISTS(SELECT 1 FROM orders
        WHERE order_id=s.order_id AND buyer_id=p_buyer) OR s.otp_digest IS NULL OR s.otp_consumed_at IS NOT NULL
        OR s.otp_expires_at<=clock_timestamp() OR s.otp_attempt_count>=5 THEN RETURN FALSE; END IF;
    UPDATE shipments SET otp_attempt_count=otp_attempt_count+1,
        otp_consumed_at=CASE WHEN otp_digest=p_digest THEN clock_timestamp() END WHERE shipment_id=p_shipment;
    IF s.otp_digest<>p_digest THEN RETURN FALSE; END IF;
    RETURN og_confirm_direct_handover(p_shipment);
END;
$function$

functions.og_early_complete_order:
CREATE OR REPLACE FUNCTION public.og_early_complete_order(p_order bigint, p_buyer bigint, p_warning text, p_command text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
DECLARE o orders;
BEGIN
    SELECT * INTO STRICT o FROM orders WHERE order_id=p_order FOR UPDATE;
    IF EXISTS(SELECT 1 FROM order_events WHERE command_key=p_command AND order_id=p_order AND actor_id=p_buyer
        AND event_type='EARLY_COMPLETION_ACCEPTED') THEN RETURN TRUE; END IF;
    IF o.workflow_model<>'UC83' OR o.buyer_id<>p_buyer OR o.valid_delivered_at IS NULL
        OR NULLIF(btrim(p_warning),'') IS NULL OR o.status<>'DELIVERED' OR og_order_has_blocking_case(p_order)
        OR EXISTS(SELECT 1 FROM money_holds h JOIN order_fund_components c USING(component_id)
            WHERE c.order_id=p_order AND h.closed_at IS NULL) THEN
        RAISE EXCEPTION 'Early completion needs Buyer warning consent and no blockers' USING ERRCODE='23514'; END IF;
    UPDATE orders SET early_completed_at=clock_timestamp(),early_completion_warning_version=p_warning WHERE order_id=p_order;
    INSERT INTO order_events(event_id,order_id,actor_id,event_type,metadata,command_key)
        VALUES(gen_random_uuid(),p_order,p_buyer,'EARLY_COMPLETION_ACCEPTED',jsonb_build_object('warning_version',p_warning),p_command);
    RETURN TRUE;
END;
$function$

functions.og_guard_admin_dispatch:
CREATE OR REPLACE FUNCTION public.og_guard_admin_dispatch()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
BEGIN
    IF NOT og_has_role(NEW.sender_id,'ADMIN') THEN
        RAISE EXCEPTION 'Only Admin sends manual dispatch' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$function$

functions.og_guard_fund_component:
CREATE OR REPLACE FUNCTION public.og_guard_fund_component()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
DECLARE o orders; expected NUMERIC;
BEGIN
    IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Fund component history retained' USING ERRCODE='23514'; END IF;
    IF TG_OP='UPDATE' THEN
        IF ROW(NEW.component_id,NEW.order_id,NEW.allocation_id,NEW.late_confirmation_id,NEW.component_type,
            NEW.confirmed_amount,NEW.funding_reference,NEW.confirmed_at) IS DISTINCT FROM
            ROW(OLD.component_id,OLD.order_id,OLD.allocation_id,OLD.late_confirmation_id,OLD.component_type,
            OLD.confirmed_amount,OLD.funding_reference,OLD.confirmed_at) OR pg_trigger_depth()<2 THEN
            RAISE EXCEPTION 'Money amount/source immutable; balances change through operations only' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;
    SELECT * INTO STRICT o FROM orders WHERE order_id=NEW.order_id FOR UPDATE;
    expected:=CASE NEW.component_type
        WHEN 'GOODS_CASH' THEN o.subtotal-o.voucher_discount_amount-o.points_discount_amount
        WHEN 'SHIPPING_CASH' THEN o.shipping_fee-o.shipping_discount_amount
        WHEN 'PLATFORM_GOODS_SUBSIDY' THEN o.voucher_discount_amount+o.points_discount_amount
        WHEN 'PLATFORM_SHIPPING_SUBSIDY' THEN o.shipping_discount_amount
        WHEN 'LATE_PAYMENT_CASH' THEN o.total_amount END;
    IF o.workflow_model<>'UC83' OR NEW.confirmed_amount<>expected
        OR NEW.reserved_amount<>0 OR NEW.refunded_amount<>0 OR NEW.released_amount<>0 OR NEW.version<>0
        OR (NEW.component_type='LATE_PAYMENT_CASH' AND NOT EXISTS(
            SELECT 1 FROM payment_confirmations c JOIN payment_intents i USING(intent_id)
            WHERE c.confirmation_id=NEW.late_confirmation_id AND c.disposition='RECONCILIATION'
                AND i.group_id=o.group_id))
        OR (NEW.component_type LIKE 'PLATFORM_%' AND o.total_amount>0 AND NOT EXISTS(
            SELECT 1 FROM payment_allocations WHERE order_id=o.order_id)) THEN
        RAISE EXCEPTION 'Fund component must equal its confirmed order source' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$function$

functions.og_guard_intent_attempt:
CREATE OR REPLACE FUNCTION public.og_guard_intent_attempt()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
BEGIN
    IF NEW.intent_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM payment_intents
        WHERE intent_id=NEW.intent_id AND expected_amount=NEW.amount AND currency=NEW.currency) THEN
        RAISE EXCEPTION 'Attempt amount/currency differs from intent' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$function$

functions.og_guard_listing_charge:
CREATE OR REPLACE FUNCTION public.og_guard_listing_charge()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM listing_fee_assessments WHERE assessment_id=NEW.assessment_id
        AND amount_due=NEW.amount AND amount_due>0) THEN
        RAISE EXCEPTION 'Listing fee charge must equal positive assessment due' USING ERRCODE='23514';
    END IF;
    IF TG_OP='UPDATE' AND (NEW.assessment_id<>OLD.assessment_id OR NEW.amount<>OLD.amount
        OR (OLD.state='CONFIRMED' AND NEW IS DISTINCT FROM OLD)) THEN
        RAISE EXCEPTION 'Confirmed listing charge is immutable' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$function$

functions.og_guard_payment_intent:
CREATE OR REPLACE FUNCTION public.og_guard_payment_intent()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
BEGIN
    IF NEW.purpose='CHECKOUT_GROUP' AND NOT EXISTS(
        SELECT 1 FROM checkout_groups WHERE group_id=NEW.group_id AND expected_total=NEW.expected_amount
            AND payment_due_at=NEW.deadline AND payment_method=NEW.payment_method) THEN
        RAISE EXCEPTION 'Payment amount/deadline/method differs from checkout' USING ERRCODE='23514';
    END IF;
    IF NEW.purpose='LISTING_FEE' AND NOT EXISTS(
        SELECT 1 FROM listing_fee_charges WHERE charge_id=NEW.listing_charge_id AND amount=NEW.expected_amount) THEN
        RAISE EXCEPTION 'Payment differs from listing fee charge' USING ERRCODE='23514';
    END IF;
    IF TG_OP='UPDATE' AND ROW(NEW.purpose,NEW.group_id,NEW.listing_charge_id,NEW.expected_amount,NEW.currency,
        NEW.payment_method,NEW.deadline,NEW.created_at,NEW.command_key)
        IS DISTINCT FROM ROW(OLD.purpose,OLD.group_id,OLD.listing_charge_id,OLD.expected_amount,OLD.currency,
        OLD.payment_method,OLD.deadline,OLD.created_at,OLD.command_key) THEN
        RAISE EXCEPTION 'Payment intent snapshot is immutable' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$function$

functions.og_guard_pickup_attempt:
CREATE OR REPLACE FUNCTION public.og_guard_pickup_attempt()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
DECLARE s shipments;
BEGIN
    SELECT * INTO STRICT s FROM shipments WHERE shipment_id=NEW.shipment_id FOR UPDATE;
    IF s.workflow_model<>'UC83' OR s.leg<>'RETURN' OR NEW.attempted_at<s.initiated_at OR NEW.attempted_at>s.pickup_deadline
       OR NEW.attempt_no<>(SELECT count(*)+1 FROM pickup_attempts WHERE shipment_id=s.shipment_id)
       OR (SELECT count(*) FROM pickup_attempts WHERE shipment_id=s.shipment_id AND outcome='FAILED')>=3
       OR EXISTS(SELECT 1 FROM pickup_attempts WHERE shipment_id=s.shipment_id AND outcome='PICKED_UP')
       OR NOT EXISTS(SELECT 1 FROM shipment_events WHERE event_id=NEW.source_event_id AND shipment_id=s.shipment_id) THEN
        RAISE EXCEPTION 'Pickup deadline/count/source exceeded' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$function$

functions.og_guard_review_parties:
CREATE OR REPLACE FUNCTION public.og_guard_review_parties()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
DECLARE o orders;
BEGIN
    SELECT * INTO STRICT o FROM orders WHERE order_id=NEW.order_id;
    IF NOT ((NEW.reviewer_id=o.buyer_id AND NEW.reviewee_id=o.seller_id)
        OR (NEW.reviewer_id=o.seller_id AND NEW.reviewee_id=o.buyer_id))
        OR (o.workflow_model='UC83' AND o.valid_delivered_at IS NULL)
        OR (o.workflow_model='LEGACY_V14' AND o.status NOT IN ('DELIVERED','COMPLETED')) THEN
        RAISE EXCEPTION 'Review requires delivered order and its two parties' USING ERRCODE='23514';
    END IF;
    IF TG_OP='UPDATE' THEN
        IF ROW(NEW.order_id,NEW.reviewer_id,NEW.reviewee_id) IS DISTINCT FROM ROW(OLD.order_id,OLD.reviewer_id,OLD.reviewee_id) THEN
            RAISE EXCEPTION 'Review identity immutable' USING ERRCODE='23514';
        END IF;
        INSERT INTO review_revisions(review_id,original_record) VALUES(OLD.review_id,to_jsonb(OLD));
    END IF;
    RETURN NEW;
END;
$function$

functions.og_guard_revision_media:
CREATE OR REPLACE FUNCTION public.og_guard_revision_media()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
DECLARE parent product_revisions; n INTEGER;
BEGIN
    IF TG_OP<>'INSERT' THEN
        SELECT * INTO STRICT parent FROM product_revisions WHERE revision_id=OLD.revision_id FOR UPDATE;
        IF parent.state<>'DRAFT' THEN
            RAISE EXCEPTION 'Submitted revision media is immutable' USING ERRCODE='23514';
        END IF;
        IF TG_OP='DELETE' THEN RETURN OLD; END IF;
        IF NEW.revision_id<>OLD.revision_id THEN
            RAISE EXCEPTION 'Cannot move media between revisions' USING ERRCODE='23514';
        END IF;
    ELSE
        SELECT * INTO STRICT parent FROM product_revisions WHERE revision_id=NEW.revision_id FOR UPDATE;
    END IF;
    IF parent.state<>'DRAFT' OR parent.provenance<>'UC83' THEN
        RAISE EXCEPTION 'Only current draft accepts media' USING ERRCODE='23514';
    END IF;
    SELECT count(*) INTO n FROM revision_media WHERE revision_id=NEW.revision_id
        AND media_type=NEW.media_type AND revision_media_id IS DISTINCT FROM NEW.revision_media_id;
    IF n >= (CASE NEW.media_type WHEN 'IMAGE' THEN 5 ELSE 2 END) THEN
        RAISE EXCEPTION 'Revision media count exceeded' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$function$

functions.og_guard_reward_account:
CREATE OR REPLACE FUNCTION public.og_guard_reward_account()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP='DELETE' OR (TG_OP='INSERT' AND (NEW.balance<>0 OR NEW.version<>0))
        OR (TG_OP='UPDATE' AND (NEW.user_id<>OLD.user_id OR pg_trigger_depth()<2)) THEN
        RAISE EXCEPTION 'Reward balance only changes through ledger' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$function$

functions.og_guard_voucher_policy:
CREATE OR REPLACE FUNCTION public.og_guard_voucher_policy()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
DECLARE v vouchers;
BEGIN
    SELECT * INTO STRICT v FROM vouchers WHERE voucher_id=NEW.voucher_id;
    IF NOT og_has_role(NEW.created_by,'ADMIN') OR v.voucher_type='BUYER_FEE_DISCOUNT' THEN
        RAISE EXCEPTION 'Admin authors canonical goods/shipping policies' USING ERRCODE='23514'; END IF;
    NEW.benefit_component:=COALESCE(NEW.benefit_component,CASE v.voucher_type WHEN 'SHIPPING_DISCOUNT' THEN 'SHIPPING' ELSE 'GOODS' END);
    NEW.discount_type:=COALESCE(NEW.discount_type,v.discount_type);
    NEW.discount_value:=COALESCE(NEW.discount_value,v.discount_value);
    NEW.max_discount_amount:=COALESCE(NEW.max_discount_amount,v.max_discount_amount);
    NEW.min_eligible_amount:=COALESCE(NEW.min_eligible_amount,v.min_order_amount);
    RETURN NEW;
END;
$function$

functions.og_apply_seller_decision:
CREATE OR REPLACE FUNCTION public.og_apply_seller_decision()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
DECLARE p seller_profiles;
BEGIN
    NEW.decided_at:=clock_timestamp();
    SELECT * INTO STRICT p FROM seller_profiles WHERE seller_profile_id=NEW.seller_profile_id FOR UPDATE;
    IF p.state<>'PENDING_REVIEW' OR p.revision_no<>NEW.revision_no OR NOT og_has_role(NEW.reviewed_by,'KTV') THEN
        RAISE EXCEPTION 'Only KTV can decide current seller profile' USING ERRCODE='23514';
    END IF;
    IF NEW.outcome='APPROVED' AND (p.pickup_address_id IS NULL
        OR NOT (p.bank_snapshot ?& ARRAY['bank_name','account_number','account_holder'])
        OR NOT EXISTS(SELECT 1 FROM ekyc_profiles e JOIN ekyc_decisions d USING(profile_id)
                       WHERE e.profile_id=p.ekyc_profile_id AND e.state='VERIFIED' AND d.outcome='VERIFIED'
                         AND e.reference_expires_at>NEW.decided_at)) THEN
        RAISE EXCEPTION 'Seller prerequisites incomplete' USING ERRCODE='23514';
    END IF;
    NEW.profile_snapshot := to_jsonb(p);
    UPDATE seller_profiles SET state=NEW.outcome,updated_at=NEW.decided_at WHERE seller_profile_id=p.seller_profile_id;
    IF NEW.outcome='APPROVED' THEN
        INSERT INTO user_roles(user_id,role_id,granted_by)
            SELECT p.user_id,role_id,NEW.reviewed_by FROM roles WHERE role_name='SELLER'
            ON CONFLICT(user_id,role_id) DO NOTHING;
    END IF;
    RETURN NEW;
END;
$function$

functions.og_confirm_zero_checkout:
CREATE OR REPLACE FUNCTION public.og_confirm_zero_checkout()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
DECLARE g checkout_groups;
BEGIN
    SELECT * INTO STRICT g FROM checkout_groups WHERE group_id=NEW.group_id FOR UPDATE;
    NEW.confirmed_at:=clock_timestamp();
    IF g.expected_total<>0 OR g.state<>'READY' OR NEW.confirmed_at>=g.payment_due_at
        OR NOT EXISTS(SELECT 1 FROM orders WHERE group_id=g.group_id)
        OR EXISTS(SELECT 1 FROM orders WHERE group_id=g.group_id AND (total_amount<>0 OR status<>'PAYMENT_PENDING'))
        OR EXISTS(SELECT 1 FROM payment_intents WHERE group_id=g.group_id) THEN
        RAISE EXCEPTION 'Zero checkout needs an in-time, unpaid, fully subsidized group' USING ERRCODE='23514';
    END IF;
    UPDATE orders SET status='PAID_HELD',paid_confirmed_at=NEW.confirmed_at,
        seller_accept_due_at=NEW.confirmed_at+INTERVAL '2 days' WHERE group_id=g.group_id;
    UPDATE inventory_reservations r SET state='FUNDED' FROM order_items i JOIN orders o USING(order_id)
        WHERE r.order_item_id=i.order_item_id AND o.group_id=g.group_id AND r.state='HELD';
    UPDATE checkout_groups SET state='PAID' WHERE group_id=g.group_id;
    RETURN NEW;
END;
$function$

functions.og_guard_discount_source:
CREATE OR REPLACE FUNCTION public.og_guard_discount_source()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
DECLARE gid UUID; pid BIGINT;
BEGIN
    SELECT o.group_id,i.product_id INTO STRICT gid,pid FROM order_items i JOIN orders o USING(order_id)
        WHERE i.order_item_id=NEW.order_item_id AND i.workflow_model='UC83';
    IF NEW.redemption_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM checkout_redemptions c
        JOIN voucher_grants g USING(grant_id) JOIN voucher_revisions r USING(revision_id)
        WHERE c.redemption_id=NEW.redemption_id AND c.group_id=gid AND r.benefit_component=NEW.component AND (r.scope='CHECKOUT' OR EXISTS(
            SELECT 1 FROM voucher_revision_products WHERE revision_id=r.revision_id AND product_id=pid))) THEN
        RAISE EXCEPTION 'Voucher allocation outside checkout/product scope' USING ERRCODE='23514';
    END IF;
    IF NEW.reward_entry_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM reward_ledger
        WHERE entry_id=NEW.reward_entry_id AND group_id=gid AND entry_type='DEBIT_CHECKOUT') THEN
        RAISE EXCEPTION 'Point allocation belongs to another checkout' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$function$

functions.og_guard_new_transaction:
CREATE OR REPLACE FUNCTION public.og_guard_new_transaction()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
DECLARE o orders;
BEGIN
    SELECT o1.* INTO STRICT o FROM order_items i JOIN orders o1 USING(order_id) WHERE i.order_item_id=NEW.order_item_id;
    PERFORM 1 FROM users WHERE user_id IN (o.buyer_id,o.seller_id) ORDER BY user_id FOR UPDATE;
    IF NOT og_has_role(o.buyer_id,'BUYER') OR NOT og_has_role(o.seller_id,'SELLER')
        OR EXISTS(SELECT 1 FROM account_restrictions WHERE user_id IN (o.buyer_id,o.seller_id) AND closed_at IS NULL)
        OR EXISTS(SELECT 1 FROM seller_buyer_blocks WHERE seller_id=o.seller_id AND buyer_id=o.buyer_id AND unblocked_at IS NULL)
        OR NOT EXISTS(SELECT 1 FROM seller_profiles s JOIN ekyc_profiles e ON e.profile_id=s.ekyc_profile_id
            JOIN ekyc_decisions d ON d.profile_id=e.profile_id WHERE s.user_id=o.seller_id AND s.state='APPROVED'
                AND e.state='VERIFIED' AND d.outcome='VERIFIED' AND e.reference_expires_at>clock_timestamp())
        OR EXISTS(SELECT 1 FROM ekyc_profiles WHERE user_id=o.seller_id AND state IN ('DRAFT','IN_PROGRESS','PENDING')) THEN
        RAISE EXCEPTION 'New transaction blocked by identity/restriction/party block' USING ERRCODE='23514'; END IF;
    RETURN NEW;
END;
$function$

functions.og_guard_return_shipment:
CREATE OR REPLACE FUNCTION public.og_guard_return_shipment()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
DECLARE c cases;
BEGIN
    IF NEW.workflow_model='UC83' AND NEW.leg='RETURN' THEN
        SELECT * INTO STRICT c FROM cases WHERE case_id=NEW.return_case_id FOR UPDATE;
        IF c.order_id<>NEW.order_id OR c.case_type<>'RETURN' OR c.approved_at IS NULL THEN
            RAISE EXCEPTION 'Return shipment requires approval for the same order' USING ERRCODE='23514';
        END IF;
        NEW.pickup_expected_at:=c.approved_at+INTERVAL '24 hours';
        NEW.pickup_deadline:=c.approved_at+INTERVAL '3 days';
    END IF;
    IF TG_OP='UPDATE' AND NEW.workflow_model='UC83' AND
        ROW(NEW.order_id,NEW.leg,NEW.return_case_id,NEW.delivery_method,NEW.initiated_at)
        IS DISTINCT FROM ROW(OLD.order_id,OLD.leg,OLD.return_case_id,OLD.delivery_method,OLD.initiated_at) THEN
        RAISE EXCEPTION 'Shipment identity/method snapshot cannot silently change' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$function$

functions.og_record_account_status:
CREATE OR REPLACE FUNCTION public.og_record_account_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
BEGIN
    IF TG_OP='INSERT' OR NEW.status IS DISTINCT FROM OLD.status THEN
        INSERT INTO account_status_events(user_id,old_status,new_status)
            VALUES(NEW.user_id,CASE WHEN TG_OP='UPDATE' THEN OLD.status ELSE NULL END,NEW.status);
    END IF;
    RETURN NEW;
END;
$function$

functions.og_consume_auth_challenge:
CREATE OR REPLACE FUNCTION public.og_consume_auth_challenge(p_challenge uuid, p_digest text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
DECLARE c auth_challenges;
BEGIN
    SELECT * INTO STRICT c FROM auth_challenges WHERE challenge_id=p_challenge FOR UPDATE;
    IF c.state<>'OPEN' OR c.expires_at<=clock_timestamp() OR c.attempt_count>=c.max_attempts THEN RETURN FALSE; END IF;
    UPDATE auth_challenges SET attempt_count=attempt_count+1,
        state=CASE WHEN code_digest=p_digest THEN 'CONSUMED' ELSE 'OPEN' END,
        consumed_at=CASE WHEN code_digest=p_digest THEN clock_timestamp() END WHERE challenge_id=c.challenge_id;
    RETURN c.code_digest=p_digest;
END;
$function$

functions.og_guard_export_authority:
CREATE OR REPLACE FUNCTION public.og_guard_export_authority()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
BEGIN
    IF NOT og_has_role(NEW.requested_by,'ADMIN') THEN RAISE EXCEPTION 'Admin export only' USING ERRCODE='23514'; END IF;
    RETURN NEW;
