functions.og_guard_product_revision:
CREATE OR REPLACE FUNCTION public.og_guard_product_revision()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
BEGIN
    IF TG_OP='INSERT' THEN
        IF NEW.provenance='UC83' AND NEW.state<>'DRAFT' THEN
            RAISE EXCEPTION 'UC83 revision starts as draft' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;
    IF TG_OP='DELETE' OR OLD.state<>'DRAFT' THEN
        RAISE EXCEPTION 'Product revision history is immutable' USING ERRCODE='23514';
    END IF;
    IF NEW.state='SUBMITTED' AND (
        (SELECT count(*) FROM revision_media WHERE revision_id=NEW.revision_id AND media_type='IMAGE') NOT BETWEEN 1 AND 5
        OR (SELECT count(*) FROM revision_media WHERE revision_id=NEW.revision_id AND media_type='VIDEO') NOT BETWEEN 1 AND 2) THEN
        RAISE EXCEPTION 'Submission requires images and videos' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$function$

functions.og_confirm_direct_handover:
CREATE OR REPLACE FUNCTION public.og_confirm_direct_handover(p_shipment bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
DECLARE s shipments; delivered TIMESTAMPTZ;
BEGIN
    PERFORM 1 FROM orders WHERE order_id=(SELECT order_id FROM shipments WHERE shipment_id=p_shipment) FOR UPDATE;
    SELECT * INTO STRICT s FROM shipments WHERE shipment_id=p_shipment FOR UPDATE;
    IF s.workflow_model<>'UC83' OR s.delivery_method='CARRIER' THEN
        RAISE EXCEPTION 'Direct handover only' USING ERRCODE='23514'; END IF;
    IF s.valid_delivery_at IS NOT NULL THEN RETURN TRUE; END IF;
    IF EXISTS(SELECT 1 FROM handover_confirmations WHERE shipment_id=p_shipment AND outcome='FAILED') THEN RETURN FALSE; END IF;
    IF s.otp_consumed_at IS NOT NULL THEN delivered:=s.otp_consumed_at;
    ELSIF (SELECT count(*) FROM handover_confirmations WHERE shipment_id=p_shipment AND outcome='SUCCESS')=2 THEN
        SELECT max(confirmed_at) INTO delivered FROM handover_confirmations WHERE shipment_id=p_shipment;
    ELSE RETURN FALSE; END IF;
    UPDATE shipments SET valid_delivery_at=delivered,status='DELIVERED',shipped_at=COALESCE(shipped_at,initiated_at),
        delivered_at=delivered WHERE shipment_id=p_shipment;
    IF s.leg='RETURN' THEN
        UPDATE cases SET state='POST_RETURN',valid_returned_at=delivered,seller_response_due_at=delivered+INTERVAL '2 days'
            WHERE case_id=s.return_case_id;
    ELSIF s.leg='OUTBOUND' THEN
        UPDATE orders SET status='DELIVERED',valid_delivered_at=delivered,
            return_due_at=CASE WHEN return_allowed THEN delivered+INTERVAL '3 days' END WHERE order_id=s.order_id;
    END IF;
    RETURN TRUE;
END;
$function$

functions.og_confirm_listing_receipt:
CREATE OR REPLACE FUNCTION public.og_confirm_listing_receipt()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
DECLARE c listing_fee_charges; p BIGINT;
BEGIN
    SELECT product_id INTO STRICT p FROM listing_fee_assessments a JOIN listing_fee_charges ch USING(assessment_id)
        WHERE ch.charge_id=NEW.charge_id;
    PERFORM 1 FROM products WHERE product_id=p FOR UPDATE;
    SELECT * INTO STRICT c FROM listing_fee_charges WHERE charge_id=NEW.charge_id FOR UPDATE;
    IF c.state<>'PENDING' OR NEW.amount<>c.amount THEN
        RAISE EXCEPTION 'Listing fee amount/state mismatch; reconciliation required' USING ERRCODE='23514';
    END IF;
    UPDATE listing_fee_charges SET state='CONFIRMED' WHERE charge_id=NEW.charge_id;
    RETURN NEW;
END;
$function$

functions.og_validate_canonical_role:
CREATE OR REPLACE FUNCTION public.og_validate_canonical_role()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
DECLARE role_code TEXT;
BEGIN
    IF NOT EXISTS(SELECT 1 FROM users WHERE user_id=NEW.user_id AND identity_workflow='UC83') THEN RETURN NULL; END IF;
    SELECT role_name INTO role_code FROM roles WHERE role_id=NEW.role_id;
    IF (role_code='SELLER' AND NOT EXISTS(SELECT 1 FROM seller_profiles p JOIN seller_profile_decisions d USING(seller_profile_id)
        WHERE p.user_id=NEW.user_id AND p.state='APPROVED' AND p.revision_no=d.revision_no AND d.outcome='APPROVED'))
        OR (role_code IN ('KTV','ADMIN') AND NOT og_has_role(NEW.granted_by,'ADMIN')) THEN
        RAISE EXCEPTION 'Canonical role grant requires approval authority' USING ERRCODE='23514'; END IF;
    RETURN NULL;
END;
$function$

functions.og_guard_payment_allocation:
CREATE OR REPLACE FUNCTION public.og_guard_payment_allocation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
BEGIN
    PERFORM 1 FROM payment_intents WHERE intent_id=NEW.intent_id FOR UPDATE;
    IF NOT EXISTS(SELECT 1 FROM payment_intents i JOIN payment_confirmations c USING(intent_id)
        JOIN orders o ON o.group_id=i.group_id WHERE i.intent_id=NEW.intent_id AND i.purpose='CHECKOUT_GROUP'
          AND c.confirmation_id=NEW.confirmation_id AND c.disposition='ALLOCATABLE'
          AND o.order_id=NEW.order_id AND o.total_amount=NEW.amount AND o.status='PAYMENT_PENDING') THEN
        RAISE EXCEPTION 'Allocation does not belong to eligible order/confirmed group' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$function$

functions.og_guard_quick_auth_attempt:
CREATE OR REPLACE FUNCTION public.og_guard_quick_auth_attempt()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
DECLARE s quick_auth_sessions;
BEGIN
    SELECT * INTO STRICT s FROM quick_auth_sessions WHERE session_id=NEW.session_id FOR UPDATE;
    NEW.attempted_at:=clock_timestamp();
    IF s.expires_at<=NEW.attempted_at OR s.nonmatch_count>=15 OR EXISTS(SELECT 1 FROM quick_auth_attempts
        WHERE session_id=s.session_id AND result='MATCH') OR NOT EXISTS(
        SELECT 1 FROM ekyc_profiles p JOIN ekyc_decisions d USING(profile_id)
        JOIN ekyc_private_assets a ON a.profile_id=p.profile_id WHERE p.profile_id=s.profile_id
          AND p.state='VERIFIED' AND d.outcome='VERIFIED' AND p.reference_expires_at>NEW.attempted_at
          AND a.asset_id=s.reference_asset_id AND a.asset_type='REFERENCE' AND a.deleted_at IS NULL
          AND a.expires_at>NEW.attempted_at
          AND NOT EXISTS(SELECT 1 FROM ekyc_profiles pending WHERE pending.user_id=s.user_id
              AND pending.state IN ('DRAFT','IN_PROGRESS','PENDING'))) THEN
        RAISE EXCEPTION 'Quick authentication unavailable/exhausted' USING ERRCODE='23514';
    END IF;
    IF s.last_nonmatch_at IS NOT NULL AND NEW.attempted_at<s.last_nonmatch_at+INTERVAL '3 seconds' THEN
        RAISE EXCEPTION 'Quick authentication cooldown' USING ERRCODE='23514';
    END IF;
    IF NEW.result='NON_MATCH' THEN UPDATE quick_auth_sessions SET nonmatch_count=nonmatch_count+1,
        last_nonmatch_at=NEW.attempted_at WHERE session_id=s.session_id; END IF;
    RETURN NEW;
END;
$function$

