functions.og_compute_listing_assessment:
CREATE OR REPLACE FUNCTION public.og_compute_listing_assessment()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
DECLARE r product_revisions; f listing_fee_policies;
BEGIN
    PERFORM 1 FROM products WHERE product_id=NEW.product_id FOR UPDATE;
    SELECT * INTO STRICT r FROM product_revisions WHERE revision_id=NEW.revision_id;
    IF r.state<>'SUBMITTED' OR r.provenance<>'UC83' OR NOT EXISTS (
        SELECT 1 FROM product_moderation_decisions WHERE decision_id=NEW.decision_id
            AND revision_id=r.revision_id AND decision='APPROVED') THEN
        RAISE EXCEPTION 'Fee requires approval of this revision' USING ERRCODE='23514';
    END IF;
    IF EXISTS(SELECT 1 FROM listing_fee_charges c JOIN listing_fee_assessments a USING(assessment_id)
              WHERE a.product_id=NEW.product_id AND c.state IN ('PENDING','RECONCILIATION')) THEN
        RAISE EXCEPTION 'Listing has an unresolved fee charge' USING ERRCODE='23514';
    END IF;
    NEW.assessed_at := clock_timestamp();
    SELECT * INTO STRICT f FROM listing_fee_policies WHERE policy_id=NEW.policy_id
        AND effective_from<=NEW.assessed_at AND (effective_until IS NULL OR effective_until>NEW.assessed_at);
    NEW.listed_total := r.listed_unit_price*r.quantity;
    SELECT listed_total INTO NEW.previous_approved_total FROM listing_fee_assessments
        WHERE product_id=NEW.product_id ORDER BY assessment_id DESC LIMIT 1;
    SELECT COALESCE(sum(receipt.amount),0) INTO NEW.cumulative_before FROM listing_fee_receipts receipt
        JOIN listing_fee_charges c USING(charge_id) JOIN listing_fee_assessments a USING(assessment_id)
        WHERE a.product_id=NEW.product_id;
    NEW.computed_fee := CASE WHEN NEW.listed_total<f.threshold_amount THEN f.fixed_below
        ELSE round(NEW.listed_total*f.rate_at_or_above,0) END;
    NEW.amount_due := CASE WHEN NEW.previous_approved_total IS NULL
        OR NEW.listed_total>NEW.previous_approved_total
        THEN greatest(0,NEW.computed_fee-NEW.cumulative_before) ELSE 0 END;
    RETURN NEW;
END;
$function$

functions.og_guard_payment_confirmation:
CREATE OR REPLACE FUNCTION public.og_guard_payment_confirmation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
DECLARE i payment_intents;
BEGIN
    SELECT * INTO STRICT i FROM payment_intents WHERE intent_id=NEW.intent_id FOR UPDATE;
    IF NEW.amount<>i.expected_amount OR NEW.provider<>i.payment_method OR NOT EXISTS(SELECT 1 FROM payment_attempts
        WHERE attempt_id=NEW.attempt_id AND intent_id=i.intent_id AND provider=NEW.provider)
        OR (NEW.provider='VNPAY' AND NOT EXISTS(
            SELECT 1 FROM payment_ipn_events e JOIN payment_ipn_raw_receipts r USING(receipt_id)
            WHERE e.event_id=NEW.ipn_event_id AND e.attempt_id=NEW.attempt_id AND e.intent_id=i.intent_id
                AND r.verification_status='VERIFIED' AND e.vnp_amount=NEW.amount
                AND e.processing_outcome IN ('APPLIED_SUCCESS','APPLIED_EXPIRED_ORDER','APPLIED_DUPLICATE_CHARGE'))) THEN
        RAISE EXCEPTION 'Confirmation source/amount/reference not verified' USING ERRCODE='23514';
    END IF;
    NEW.confirmed_at:=clock_timestamp();
    IF i.state<>'PENDING' OR NEW.confirmed_at>=i.deadline OR
       (i.group_id IS NOT NULL AND EXISTS(SELECT 1 FROM orders WHERE group_id=i.group_id AND status='CANCELLED')) THEN
        NEW.disposition:='RECONCILIATION';
    END IF;
    IF NEW.disposition='ALLOCATABLE' THEN
        UPDATE payment_intents SET state='CONFIRMED' WHERE intent_id=i.intent_id;
        IF i.purpose='LISTING_FEE' THEN
            INSERT INTO listing_fee_receipts(receipt_id,charge_id,provider,provider_transaction_id,amount,confirmed_at)
                VALUES(NEW.confirmation_id,i.listing_charge_id,NEW.provider,NEW.provider_transaction_id,NEW.amount,NEW.confirmed_at);
        END IF;
    ELSE
        UPDATE payment_intents SET state='RECONCILIATION' WHERE intent_id=i.intent_id;
    END IF;
    RETURN NEW;
END;
$function$

functions.og_guard_settlement_operation:
CREATE OR REPLACE FUNCTION public.og_guard_settlement_operation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
DECLARE c order_fund_components; o orders; old_reserved BOOLEAN; new_reserved BOOLEAN;
BEGIN
    IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Settlement history retained' USING ERRCODE='23514'; END IF;
    SELECT * INTO STRICT o FROM orders WHERE order_id=(SELECT order_id FROM order_fund_components WHERE component_id=NEW.component_id) FOR UPDATE;
    SELECT * INTO STRICT c FROM order_fund_components WHERE component_id=NEW.component_id FOR UPDATE;
    IF TG_OP='INSERT' AND NEW.state<>'REQUESTED' THEN RAISE EXCEPTION 'Operation starts requested' USING ERRCODE='23514'; END IF;
    IF TG_OP='UPDATE' AND (OLD.state='CONFIRMED' OR
        ROW(NEW.component_id,NEW.operation_type,NEW.amount,NEW.cause_type,NEW.case_decision_id,NEW.recipient_user_id,NEW.command_key)
        IS DISTINCT FROM ROW(OLD.component_id,OLD.operation_type,OLD.amount,OLD.cause_type,OLD.case_decision_id,OLD.recipient_user_id,OLD.command_key)) THEN
        RAISE EXCEPTION 'Settlement identity/confirmed result immutable' USING ERRCODE='23514';
    END IF;
    IF NEW.state IN ('REQUESTED','PROCESSING','CONFIRMED') THEN
        IF EXISTS(SELECT 1 FROM money_holds WHERE component_id=c.component_id AND closed_at IS NULL) THEN
            RAISE EXCEPTION 'Money component has active hold' USING ERRCODE='23514';
        END IF;
        IF c.component_type IN ('GOODS_CASH','PLATFORM_GOODS_SUBSIDY') AND og_order_has_blocking_case(o.order_id) THEN
            RAISE EXCEPTION 'Order has blocking case' USING ERRCODE='23514';
        END IF;
        IF NEW.operation_type='REFUND_BUYER' THEN
            IF NEW.recipient_user_id IS DISTINCT FROM o.buyer_id OR c.component_type NOT IN ('GOODS_CASH','SHIPPING_CASH','LATE_PAYMENT_CASH')
              OR NEW.amount<>c.confirmed_amount
              OR (c.component_type='SHIPPING_CASH' AND (NEW.cause_type<>'CANCELLATION' OR o.purchase_shipping_used_at IS NOT NULL))
              OR NOT ((NEW.cause_type='CANCELLATION' AND o.status='CANCELLED')
                OR (NEW.cause_type='RETURN' AND og_case_settlement_allowed(NEW.case_decision_id,o.order_id,'RETURN'))
                OR (NEW.cause_type='RECONCILIATION' AND c.component_type='LATE_PAYMENT_CASH')) THEN
                RAISE EXCEPTION 'Buyer refund not eligible/full net component' USING ERRCODE='23514';
            END IF;
        ELSIF NEW.operation_type='RELEASE_SELLER' THEN
            IF NEW.recipient_user_id IS DISTINCT FROM o.seller_id
                OR c.component_type NOT IN ('GOODS_CASH','PLATFORM_GOODS_SUBSIDY')
                OR NOT ((NEW.cause_type='COMPLETION' AND o.valid_delivered_at IS NOT NULL
                    AND (o.early_completed_at IS NOT NULL OR clock_timestamp()>=o.valid_delivered_at+INTERVAL '3 days'))
                    OR (NEW.cause_type='EXEMPTION' AND og_case_settlement_allowed(NEW.case_decision_id,o.order_id,'EXEMPTION'))) THEN
                RAISE EXCEPTION 'Seller release is not eligible' USING ERRCODE='23514';
            END IF;
        ELSIF NEW.operation_type='RELEASE_CARRIER' THEN
            IF c.component_type NOT IN ('SHIPPING_CASH','PLATFORM_SHIPPING_SUBSIDY') OR o.purchase_shipping_used_at IS NULL THEN
                RAISE EXCEPTION 'Shipping was not used' USING ERRCODE='23514';
            END IF;
        ELSIF c.component_type NOT LIKE 'PLATFORM_%' OR NOT (
            (NEW.cause_type='CANCELLATION' AND o.status='CANCELLED') OR
            (NEW.cause_type='RETURN' AND og_case_settlement_allowed(NEW.case_decision_id,o.order_id,'RETURN'))) THEN
            RAISE EXCEPTION 'Platform return requires subsidy component' USING ERRCODE='23514';
        END IF;
    END IF;
    old_reserved:=TG_OP='UPDATE' AND OLD.state IN ('REQUESTED','PROCESSING');
    new_reserved:=NEW.state IN ('REQUESTED','PROCESSING');
    IF (TG_OP='INSERT' OR (TG_OP='UPDATE' AND OLD.state='FAILED')) AND new_reserved THEN
        UPDATE order_fund_components SET reserved_amount=reserved_amount+NEW.amount,version=version+1
            WHERE component_id=c.component_id;
    ELSIF old_reserved AND NEW.state IN ('FAILED','CONFIRMED') THEN
        UPDATE order_fund_components SET reserved_amount=reserved_amount-NEW.amount,
            refunded_amount=refunded_amount+CASE WHEN NEW.state='CONFIRMED' AND NEW.operation_type IN ('REFUND_BUYER','RETURN_PLATFORM') THEN NEW.amount ELSE 0 END,
            released_amount=released_amount+CASE WHEN NEW.state='CONFIRMED' AND NEW.operation_type IN ('RELEASE_SELLER','RELEASE_CARRIER') THEN NEW.amount ELSE 0 END,
            version=version+1 WHERE component_id=c.component_id;
    ELSIF TG_OP='UPDATE' AND NEW.state<>OLD.state AND NOT (OLD.state='REQUESTED' AND NEW.state='PROCESSING') THEN
        RAISE EXCEPTION 'Invalid settlement transition' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$function$

functions.og_validate_identity_decision:
CREATE OR REPLACE FUNCTION public.og_validate_identity_decision()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
BEGIN
    IF TG_TABLE_NAME='ekyc_profiles' THEN
        IF EXISTS(SELECT 1 FROM ekyc_profiles p WHERE p.profile_id=NEW.profile_id
            AND p.state IN ('VERIFIED','REJECTED') AND NOT EXISTS(SELECT 1 FROM ekyc_decisions d
                WHERE d.profile_id=p.profile_id AND d.outcome=p.state)) THEN
            RAISE EXCEPTION 'Final eKYC state requires KTV decision' USING ERRCODE='23514';
        END IF;
    ELSE
        IF EXISTS(SELECT 1 FROM seller_profiles p WHERE p.seller_profile_id=NEW.seller_profile_id
            AND p.state IN ('APPROVED','REJECTED') AND NOT EXISTS(SELECT 1 FROM seller_profile_decisions d
                WHERE d.seller_profile_id=p.seller_profile_id AND d.revision_no=p.revision_no AND d.outcome=p.state)) THEN
            RAISE EXCEPTION 'Final seller state requires KTV decision' USING ERRCODE='23514';
        END IF;
    END IF;
    RETURN NULL;
END;
$function$

functions.og_guard_inventory_reservation:
CREATE OR REPLACE FUNCTION public.og_guard_inventory_reservation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
DECLARE p products; o orders; i order_items; delta INTEGER;
BEGIN
    IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Reservation history is retained' USING ERRCODE='23514'; END IF;
    SELECT * INTO STRICT p FROM products WHERE product_id=NEW.product_id FOR UPDATE;
    SELECT * INTO STRICT i FROM order_items WHERE order_item_id=NEW.order_item_id;
    SELECT * INTO STRICT o FROM orders WHERE order_id=i.order_id;
    IF p.workflow_model<>'UC83' OR i.workflow_model<>'UC83' OR o.workflow_model<>'UC83'
       OR NEW.quantity<>i.quantity OR NEW.expires_at<>o.payment_due_at THEN
        RAISE EXCEPTION 'Reservation must match UC83 item and original deadline' USING ERRCODE='23514';
    END IF;
    IF TG_OP='INSERT' THEN
        IF NEW.state<>'HELD' OR p.status<>'ACTIVE' OR p.public_revision_id IS DISTINCT FROM i.product_revision_id OR p.quantity_available<NEW.quantity
           OR p.deleted_at IS NOT NULL OR clock_timestamp()>=NEW.expires_at THEN
            RAISE EXCEPTION 'Product quantity unavailable' USING ERRCODE='23514';
        END IF;
        UPDATE products SET quantity_held=quantity_held+NEW.quantity WHERE product_id=p.product_id;
    ELSE
        IF ROW(NEW.product_id,NEW.order_item_id,NEW.quantity,NEW.created_at,NEW.expires_at,NEW.command_key)
           IS DISTINCT FROM ROW(OLD.product_id,OLD.order_item_id,OLD.quantity,OLD.created_at,OLD.expires_at,OLD.command_key) THEN
            RAISE EXCEPTION 'Reservation snapshot is immutable' USING ERRCODE='23514';
        END IF;
        IF NEW.state=OLD.state THEN RETURN NEW; END IF;
        IF NOT ((OLD.state='HELD' AND NEW.state IN ('FUNDED','RELEASED'))
            OR (OLD.state='FUNDED' AND NEW.state IN ('CONSUMED','RELEASED'))) THEN
            RAISE EXCEPTION 'Invalid reservation transition' USING ERRCODE='23514';
        END IF;
        IF NEW.state='FUNDED' AND (o.paid_confirmed_at IS NULL OR o.paid_confirmed_at>OLD.expires_at
            OR o.status='CANCELLED') THEN
            RAISE EXCEPTION 'Late payment cannot fund cancelled/expired reservation' USING ERRCODE='23514';
        END IF;
        IF NEW.state='CONSUMED' AND (o.status<>'SELLER_CONFIRMED' OR o.seller_accept_due_at IS NULL
            OR clock_timestamp()>o.seller_accept_due_at) THEN
            RAISE EXCEPTION 'Seller acceptance is not eligible' USING ERRCODE='23514';
        END IF;
        IF NEW.state IN ('RELEASED','CONSUMED') THEN
            delta := CASE WHEN NEW.state='CONSUMED' THEN NEW.quantity ELSE 0 END;
            UPDATE products SET quantity_held=quantity_held-NEW.quantity,quantity_sold=quantity_sold+delta,
                status=CASE WHEN quantity_sold+delta=quantity_total THEN 'SOLD' ELSE status END
                WHERE product_id=p.product_id;
        END IF;
        NEW.changed_at:=clock_timestamp();
    END IF;
    RETURN NEW;
END;
$function$

functions.og_validate_checkout_aggregate:
CREATE OR REPLACE FUNCTION public.og_validate_checkout_aggregate()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
DECLARE g checkout_groups; gid UUID; o orders; n INTEGER;
BEGIN
    IF TG_TABLE_NAME='checkout_groups' THEN gid:=NEW.group_id;
    ELSIF TG_TABLE_NAME='orders' THEN gid:=NEW.group_id;
    ELSE SELECT group_id INTO gid FROM orders WHERE order_id=NEW.order_id; END IF;
    IF gid IS NULL THEN RETURN NULL; END IF;
    SELECT * INTO STRICT g FROM checkout_groups WHERE group_id=gid FOR UPDATE;
    IF g.expected_total<>(SELECT COALESCE(sum(total_amount),0) FROM orders WHERE group_id=gid)
       OR NOT EXISTS(SELECT 1 FROM orders WHERE group_id=gid) THEN
        RAISE EXCEPTION 'Checkout total must equal all orders' USING ERRCODE='23514';
    END IF;
    FOR o IN SELECT * FROM orders WHERE group_id=gid LOOP
        IF o.payment_due_at<>g.payment_due_at OR o.delivery_method<>g.delivery_method
            OR o.carrier_snapshot IS DISTINCT FROM g.carrier
            OR jsonb_build_object('recipient_name',o.shipping_recipient_name,'phone_number',o.shipping_phone_number,
                'province',o.shipping_province,'district',o.shipping_district,'ward',o.shipping_ward,
                'detail_address',o.shipping_detail_address)<>g.address_snapshot
            OR o.subtotal<>(SELECT COALESCE(sum(agreed_price*quantity),0) FROM order_items WHERE order_id=o.order_id)
            OR o.voucher_discount_amount<>(SELECT COALESCE(sum(voucher_allocation),0) FROM order_items WHERE order_id=o.order_id)
            OR o.points_discount_amount<>(SELECT COALESCE(sum(points_allocation),0) FROM order_items WHERE order_id=o.order_id)
            OR EXISTS(SELECT 1 FROM order_items i WHERE i.order_id=o.order_id AND NOT EXISTS(
                SELECT 1 FROM inventory_reservations r WHERE r.order_item_id=i.order_item_id AND r.quantity=i.quantity)) THEN
            RAISE EXCEPTION 'Checkout snapshots/items/reservations incomplete' USING ERRCODE='23514';
        END IF;
    END LOOP;
    RETURN NULL;
END;
$function$

functions.fn_enforce_product_media_limits:
CREATE OR REPLACE FUNCTION public.fn_enforce_product_media_limits()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
DECLARE n INTEGER;
BEGIN
    IF TG_OP='UPDATE' AND NEW.product_id<>OLD.product_id THEN
        RAISE EXCEPTION 'Cannot move media between products' USING ERRCODE='23514';
    END IF;
    PERFORM 1 FROM products WHERE product_id=NEW.product_id FOR UPDATE;
    SELECT count(*) INTO n FROM product_media WHERE product_id=NEW.product_id
        AND media_type=NEW.media_type AND media_id IS DISTINCT FROM NEW.media_id;
    IF n >= (CASE NEW.media_type WHEN 'IMAGE' THEN 5 ELSE 2 END) THEN
        RAISE EXCEPTION 'Product media limit exceeded' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$function$

functions.og_validate_intent_confirmation:
CREATE OR REPLACE FUNCTION public.og_validate_intent_confirmation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
