        AND NOT EXISTS(SELECT 1 FROM payment_confirmations c WHERE c.intent_id=i.intent_id AND disposition='ALLOCATABLE')) THEN
        RAISE EXCEPTION 'Confirmed intent needs verified confirmation' USING ERRCODE='23514';
    END IF;
