functions.og_validate_payment_allocations:
CREATE OR REPLACE FUNCTION public.og_validate_payment_allocations()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
DECLARE i payment_intents; n NUMERIC;
BEGIN
    SELECT * INTO STRICT i FROM payment_intents WHERE intent_id=NEW.intent_id FOR UPDATE;
    IF i.purpose='CHECKOUT_GROUP' AND EXISTS(SELECT 1 FROM payment_confirmations
        WHERE intent_id=i.intent_id AND disposition='ALLOCATABLE') THEN
        SELECT COALESCE(sum(amount),0) INTO n FROM payment_allocations WHERE intent_id=i.intent_id;
        IF n<>i.expected_amount OR EXISTS(SELECT 1 FROM orders o WHERE o.group_id=i.group_id
            AND NOT EXISTS(SELECT 1 FROM payment_allocations a WHERE a.order_id=o.order_id AND a.intent_id=i.intent_id)) THEN
            RAISE EXCEPTION 'Confirmed payment must allocate every order exactly' USING ERRCODE='23514';
        END IF;
    END IF;
    RETURN NULL;
END;
$function$

functions.og_validate_listing_decision_fee:
CREATE OR REPLACE FUNCTION public.og_validate_listing_decision_fee()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', '$user', 'public'
AS $function$
BEGIN
    IF NEW.revision_id IS NOT NULL AND NEW.decision='APPROVED' AND NOT EXISTS(
        SELECT 1 FROM listing_fee_assessments WHERE decision_id=NEW.decision_id) THEN
        RAISE EXCEPTION 'Approval must assess listing fee in the same transaction' USING ERRCODE='23514';
    END IF;
    RETURN NULL;
END;
$function$

functions.fn_check_product_media_requirements:
CREATE OR REPLACE FUNCTION public.fn_check_product_media_requirements()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_image_count INTEGER;
    v_video_count INTEGER;
BEGIN
    IF NEW.status IN ('PENDING', 'ACTIVE') AND (OLD.status IS NULL OR OLD.status = 'DRAFT') THEN
        SELECT COUNT(*) FILTER (WHERE media_type = 'IMAGE'),
               COUNT(*) FILTER (WHERE media_type = 'VIDEO')
        INTO v_image_count, v_video_count
        FROM product_media
        WHERE product_id = NEW.product_id;

        IF v_image_count < 1 THEN
            RAISE EXCEPTION 'Tin đăng phải có ít nhất 1 hình ảnh sản phẩm (media_type=IMAGE).';
        END IF;

        IF v_video_count < 1 THEN
            RAISE EXCEPTION 'Tin đăng đồ cũ phải có ít nhất 1 video quay cận cảnh sản phẩm (media_type=VIDEO).';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

